  SLUG_MAX_LENGTH,
  SLUG_MIN_LENGTH,
  SLUG_PATTERN,
  isReservedSlug,
} from "@/lib/slug";

/**
 * Slug validation, reusing the predicates from `@/lib/slug` so the form
