/**
 * Email address rules shared by sign-up, sign-in and password reset.
 *
 * Addresses are case-insensitive (ADR 0003 §3): they are stored lowercased and
 * compared lowercased wherever an account is looked up, so the spelling a
 * phone keyboard produces and the one typed on a laptop reach one account.
 */

/** The canonical, stored spelling of an address. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/** Sign-up was attempted for an address that already has an account. */
export class EmailTakenError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly email: string) {
    super("An account with that email address already exists.");
    this.name = "EmailTakenError";
  }
}

